package dev.zomboid.isotacz;
/** Screen-space visibility mask, drawn before HUD; sound and simulation are untouched. */
public final class Fog {
 static Object world;static long last;static int[] mask;static final int W=48,H=27;
 public static int darkness(boolean cone,boolean blocked){return cone&&!blocked?0:255;}
 static int sample(double x,double y){int a=Math.max(0,Math.min(W-1,(int)Math.floor(x))),b=Math.max(0,Math.min(H-1,(int)Math.floor(y))),c=Math.min(W-1,a+1),d=Math.min(H-1,b+1);double tx=Math.max(0,Math.min(1,x-a)),ty=Math.max(0,Math.min(1,y-b));return (int)Math.round((mask[b*W+a]*(1-tx)+mask[b*W+c]*tx)*(1-ty)+(mask[d*W+a]*(1-tx)+mask[d*W+c]*tx)*ty);}
 public static void render(Object graphics){try{Object mc=Bridge.mc(),player=R.get(mc,"player"),level=R.get(mc,"level");if(!Bridge.active()||player==null||level==null||R.get(mc,"screen")!=null){world=null;mask=null;return;}Object renderer=R.get(mc,"gameRenderer"),camera=R.call(renderer,"getMainCamera"),position=R.call(camera,"getPosition"),eye=R.call(player,"getEyePosition"),window=R.call(mc,"getWindow");double yaw=R.num(R.call(camera,"getYRot")),pitch=R.num(R.call(camera,"getXRot")),aspect=R.num(R.call(window,"getWidth"))/R.num(R.call(window,"getHeight")),fov=R.num(R.call(renderer,"callGetFov",camera,(float)R.num(R.call(camera,"getPartialTickTime")),true)),zoom=R.num(R.call(Bridge.mod(),"getZoom"));boolean ortho=R.yes(R.get(Bridge.config(),"ortho"));long now=System.nanoTime();if(world!=level||mask==null||now-last>100_000_000L){world=level;last=now;mask=new int[W*H];for(int y=0;y<H;y++)for(int x=0;x<W;x++){Rules.Ray ray=Rules.cursor(Bridge.v(position,"x"),Bridge.v(position,"y"),Bridge.v(position,"z"),yaw,pitch,2*(x+.5)/W-1,1-2*(y+.5)/H,aspect,fov,ortho,zoom);double[] o=ray.origin(),d=ray.direction();Object start=Bridge.vec(o[0],o[1],o[2]),end=Bridge.vec(o[0]+96*d[0],o[1]+96*d[1],o[2]+96*d[2]);Object context=R.make("com.cleannrooster.dungeons_iso.api.RaycastContextCull",start,end,R.get(R.type("com.cleannrooster.dungeons_iso.api.CustomShapeTypes"),"CULLED"),R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"OUTLINE"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),player);Object surface=R.call(level,"clip",context),point=R.call(surface,"getLocation");if(R.call(surface,"getType").toString().equals("MISS")){double floor=Bridge.v(eye,"y")-1.6,t=d[1]<-.001?(floor-o[1])/d[1]:-1;if(t<0||t>96){mask[y*W+x]=255;continue;}point=Bridge.vec(o[0]+t*d[0],floor,o[2]+t*d[2]);}boolean cone=Rules.inView(Bridge.v(point,"x")-Bridge.v(eye,"x"),Bridge.v(point,"z")-Bridge.v(eye,"z"),yaw);Object target=Bridge.plus(point,0,.06,0),obstruction=Bridge.clip(level,player,eye,target);boolean blocked=R.call(obstruction,"getType").toString().equals("BLOCK")&&Bridge.distance(eye,R.call(obstruction,"getLocation"))<Bridge.distance(eye,target)-.15;mask[y*W+x]=darkness(cone,blocked);}}
 int width=((Number)R.call(graphics,"guiWidth")).intValue(),height=((Number)R.call(graphics,"guiHeight")).intValue();for(int y=0;y<H*3;y++)for(int x=0;x<W*3;x++){int alpha=sample((x+.5)/3-.5,(y+.5)/3-.5);if(alpha!=0)R.call(graphics,"fill",x*width/(W*3),y*height/(H*3),(x+1)*width/(W*3),(y+1)*height/(H*3),alpha<<24);}
 }catch(Throwable e){Bridge.warn("field of view terrain mask",e);}}
}
